head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > copyOption]<br/>Body Cell 값을 복사(Ctrl+C) 또는 잘라내기(Ctrl+X)할 때 화면에 표시된 값을 반영할지 설정합니다.",
    "validation" : [
        "Column 의 copyOption 속성이 설정된 경우 GridView 의 copyOption 속성은 무시됩니다.",
        "'dataList'(기본값) 설정 시 복사/잘라내기 시 DataCollection 에 저장된 원본 데이터(displayFormat, customFormatter 등 포맷 미적용)가 클립보드에 복사됩니다.",
        "'display' 설정 시 복사/잘라내기 시 GridView 에 표시된 값(displayFormat, customFormatter 등 포맷 적용)이 클립보드에 복사됩니다.",
        "Body Cell 값이 텍스트 단위로 선택된 경우 copyOption 은 항상 'display' 로 동작하며, 따라서 copyType='native' 인 경우 copyOption 은 항상 'display' 로 동작합니다.",
        "잘라내기(Ctrl+X) 시 클립보드에 복사되는 값은 copyOption 속성으로 정해지고, 원본 데이터는 빈 문자열로 초기화됩니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - 편집 가능한 GridView (gBody 4 Column, editType=text), 데이터 4건
//  - col2(금액) 에 displayFormat="#,##0" 적용 → 원본("1234567") 과 표시값("1,234,567") 이 다름
//    · copyOption=dataList → 원본("1234567") 복사 / display → 표시값("1,234,567") 복사
//  - col3 에는 Column 단위 copyOption="display" 를 고정 설정 → GridView copyOption 과 무관하게 항상 display (validation #1)
//  - copyOption 은 con_copyOption 선택값(미설정/dataList/display) 으로 GridView 에 적용 (정적 item + getValue)
//    · 미설정("") 이면 copyOption 속성 자체를 제외 → 기본값 "dataList" 동작
//  - copyType 은 con_copyType 선택값(default/native) 으로 적용 (native 시 copyOption 무관 항상 display)
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 (con_ 옵션을 properties 객체로 모아 createCList 로 속성 문자열 생성, 빈값 자동 제외)
    let conCopyOption = con_copyOption.getValue();
    let conCopyType = con_copyType.getValue();

    let properties = {
        focusMode : "cell",
        copyType : conCopyType
    };
    // 미설정("") 일 때는 copyOption 속성 자체를 제외 (기본값 dataList 동작)
    if (conCopyOption !== "") {
        properties.copyOption = conCopyOption;
    }
    let cList = $c.gcm.createCList(properties);

    // 복사 이벤트(oncustomcopy/oncustomcut) 바인딩
    let eList = $c.gcm.createEList(["oncustomcopy", "oncustomcut"]);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    let lblCopyOption = (conCopyOption === '') ? '미설정(기본 dataList)' : conCopyOption;
    $c.gcm.createLabel('label="copyOption=' + lblCopyOption + ', copyType=' + conCopyType + ' (col2: displayFormat #,##0 / col3: Column copyOption=display 고정)"', '', 'label1');

    // dataList 생성 (col2 는 금액 원본값 — displayFormat 으로 천단위 콤마 표시)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { col1 : "RowA", col2 : "1234567", col3 : "9876543", col4 : "TextA" },
        { col1 : "RowB", col2 : "2200000", col3 : "150000",  col4 : "TextB" },
        { col1 : "RowC", col2 : "30500",   col3 : "7000000", col4 : "TextC" },
        { col1 : "RowD", col2 : "888",     col3 : "42",      col4 : "TextD" }
    ]);

    // target 생성 (편집 가능 그리드 : gBody Column 에 editType="text")
    //  - col2 : displayFormat="#,##0" (원본 != 표시)
    //  - col3 : Column 단위 copyOption="display" 고정 + displayFormat="#,##0" (GridView 설정 무시 확인용)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' ' + eList + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:520px;height:240px;">';
    strTarget += '<w2:caption style="" id="caption1" value="copyOption 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column1" value="이름"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column2" value="금액(GridView)"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="column3" value="금액(Column=display)"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column4" value="비고"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col1" editType="text"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="col2" editType="text" dataType="number" displayFormat="#,##0"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="col3" editType="text" dataType="number" displayFormat="#,##0" copyOption="display"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col4" editType="text"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// con_copyOption 변경 시 Target 재생성 안내 (con 변경은 Target 재생성 버튼으로 반영)
scwin.con_copyOption_onchange = function () {
    // 별도 동작 없음 (Target 재생성 버튼 클릭 시 comp_init 에서 반영)
}



// con_copyType 변경 시 Target 재생성 안내 (con 변경은 Target 재생성 버튼으로 반영)
scwin.con_copyType_onchange = function () {
    // 별도 동작 없음 (Target 재생성 버튼 클릭 시 comp_init 에서 반영)
}



// 포커스된 셀 위치 반환 (없으면 null)
scwin.getFocusedCellPos = function () {
    let rowIndex = target1.getFocusedRowIndex();
    let colIndex = target1.getFocusedColumnIndex();
    if (rowIndex === undefined || rowIndex === null || rowIndex < 0 || colIndex === undefined || colIndex === null || colIndex < 0) {
        return null;
    }
    return { rowIndex : rowIndex, colIndex : colIndex };
}



// 붙여넣기 대상(txa_pasteTarget) 값 변경(붙여넣기) 시점에 출력
//  - 붙여넣은 값 : 클립보드에 복사된 값 (copyOption=dataList → 원본 / display → 표시값)
//  - 포커스 셀의 원본 데이터(getCellData) 와 표시값(getCellDisplayData) 을 함께 출력하여 어느 쪽이 복사됐는지 비교
//  - 잘라내기(Ctrl+X) 이후라면 원본 데이터가 "" 로 초기화되어 있어야 함
scwin.txa_pasteTarget_onchange = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let pasted = txa_pasteTarget.getValue();
    bottom.setReturnValue("붙여넣은 값(클립보드) : " + pasted);

    let pos = scwin.getFocusedCellPos();
    if (pos) {
        let colID = target1.getColumnID(pos.colIndex);
        let rawData = dlt_bind.getCellData(pos.rowIndex, colID);
        let displayData = target1.getCellDisplayData(pos.rowIndex, pos.colIndex);
        bottom.setReturnValue("포커스 셀 원본 데이터(getCellData) : " + rawData);
        bottom.setReturnValue("포커스 셀 표시값(getCellDisplayData) : " + displayData);
    }
}



// oncustomcopy 핸들러 (복사 시도 시 발생 — 출력 없음, no-op)
scwin.target1_oncustomcopy = function (e) {
}



// oncustomcut 핸들러 (잘라내기 시도 시 발생 — 출력 없음, no-op)
scwin.target1_oncustomcut = function (e) {
}
